        syslog(LOG_ERR, "Memory allocation failed for array of size %zu", size);
        return NULL; // Handle memory error 
    }

    // Initialize array elements (optional)
    pthread_mutex_init(&array_mutex, NULL); // Initialize mutex

    return array;
}



void destroy_array(Record* array, size_t size) {
    free(array);
    pthread_mutex_destroy(&array_mutex); 
}



