using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Newtonsoft.Json;

public class ConfigurableUIApp
{
    private IConfiguration _config;
    private HttpClient _httpClient;
    private Dictionary<string, dynamic> _cachedConfig = new Dictionary<string, dynamic>();

    public ConfigurableUIApp(IConfiguration config)
    {
        _config = config;
        _httpClient = new HttpClient();
    }

    public async Task LoadConfigurationAsync()
    {
        var apiUrl = _config.GetValue<string>("ApiSettings:BaseUrl");
        try
        {
            var response = await _httpClient.GetAsync($"{apiUrl}/configuration");
            if (response.IsSuccessStatusCode)
            {
                var content = await response.Content.ReadAsStringAsync();
                var configData = JsonConvert.DeserializeObject<dynamic>(content);

                lock (_cachedConfig)
                {
                    _cachedConfig = configData;
                }
            }
            else
            {
                // Handle API errors gracefully
                Console.WriteLine($"API request failed: {response.StatusCode}");
            }
        }
        catch (Exception ex)
        {
            // Log exception and handle gracefully
            Console.WriteLine($"Error loading configuration: {ex.Message}");
        }
    }

    public dynamic GetConfigurationValue(string key)
    {
        lock (_cachedConfig)
        {
            if (_cachedConfig.TryGetValue(key, out var value))
            {
                return value;
            }
            else
            {
                // Handle missing values gracefully
                Console.WriteLine($"Missing configuration value: {key}");
                return null;
            }
        }
    }
}
``` 



