const express = require('express');
const fs = require('fs');
const path = require('path');
const async = require('async');

const app = express();
const port = 3000; // Adjust as needed

app.use(express.json());

// Configuration (adjust as needed)
const directoryPath = './input'; 
const fileExtension = '.json';

function processFile(filePath, callback) {
  fs.readFile(filePath, 'utf8', (err, data) => {
    if (err) {
      console.error(`Error processing ${filePath}: ${err}`);
      return callback(err);
    }

    try {
      const jsonData = JSON.parse(data);
      callback(null, jsonData); 
    } catch (parseError) {
      console.error(`Error parsing ${filePath}: ${parseError}`);
      callback(parseError);
    }
  });
}

app.get('/process', async (req, res) => {
  const files = fs.readdirSync(directoryPath).filter(file => 
    path.extname(file) === fileExtension
  );

  async.mapLimit(files, 10, processFile, (err, results) => {
    if (err) {
      res.status(500).json({ error: err.message });
      return;
    }

    res.json(results);
  });
});


app.listen(port, () => {
  console.log(`Service listening on port ${port}`);
}); 
```




 **Explanation:**

*   **Dependencies:** The code imports necessary Node.js modules: `express` for building the REST API, `fs` for file system operations, `path` for working with file paths, and `async` for asynchronous processing.
