// JavaScript Component (Buffer Manipulation)
const fs = require('fs'); // Assuming file system access is needed

function copyBytes(dataStream, byteCount, offset = 0) {
  if (byteCount <= 0 || !Number.isInteger(byteCount) || offset < 0) {
    throw new Error("Invalid input parameters.");
  }
  let totalCopied = 0;
  let dataBuffer = Buffer.allocUnsafe(byteCount); // Create a new buffer

  while (totalCopied < byteCount) {
    const chunkSize = Math.min(dataStream.length - offset, byteCount - totalCopied);
    dataStream.copy(dataBuffer, totalCopied, offset);
    totalCopied += chunkSize;
    offset += chunkSize; 
  }

  return dataBuffer;
}

// Example usage:
const data = fs.readFileSync('example_file.bin'); // Read data from file
const copiedData = copyBytes(data, 1024); // Copy 1024 bytes


