import { Observable } from 'rxjs';
import { map, catchError } from 'rxjs/operators';
import { Injectable } from '@angular/core';

interface NodeData {
  id: string;
  content: string;
  attributes: { [key: string]: string };
  children?: NodeData[];
}

@Injectable({ providedIn: 'root' })
export class DomTraverserService {
  private cachedData = new Map<string, NodeData>();

  constructor(private http: HttpClient) {}

  traverseDom(rootNode: HTMLElement): Observable<NodeData[]> {
    return this.http.get<NodeData[]>(`/api/rootNodes/${rootNode.id}`).pipe(
      map((data) => {
        this.cachedData.set(rootNode.id, data);
        return this.populateChildren(data);
      }),
      catchError((error) => {
        console.error('Error fetching root node data:', error);
        throw error;
      })
    );
  }

  private populateChildren(node: NodeData): NodeData[] {
    const children = node.children || [];
    return children.map((child) => {
      this.cachedData.set(child.id, child);
      const apiUrl = `/api/nodes/${child.id}`;

      return this.http.get<NodeData>(apiUrl).pipe(
        map((data) => {
          this.populateChildren(data);
          return data;
        }),
        catchError((error) => {
          console.error(`Error fetching child node data: ${child.id}`, error);
          throw error;
        })
      ).toPromise();
    });
  }

  getNodeDataById(nodeId: string): NodeData | null {
    return this.cachedData.get(nodeId) || null;
  }
}



