public class DisjointPairService {

    private final int MAX_ELEMENTS = 10_000_000; // Example upper limit for array size

    private final UnionFind uf;
    private final ExecutorService threadPool;

    // Constructor, Initialization of UnionFind and ThreadPool
    public DisjointPairService() {
        this.uf = new UnionFind(MAX_ELEMENTS); 
        this.threadPool = Executors.newFixedThreadPool(10); // Example thread pool size
    }

    public int processArray(int[] array, int priority) { 
        // Thread submission to the ThreadPool
        Callable<Integer> task = () -> {
            int count = 0;  
            for (int i = 0; i < array.length; i++) {
                for (int j = i + 1; j < array.length; j++) {
                    if (uf.find(array[i]) != uf.find(array[j])) { // Efficient disjoint pair check
                        count++;
                        uf.union(array[i], array[j]); // Union sets for efficiency
                    }
                }
            } 
            return count;
        };

        try {
            Future<Integer> result = threadPool.submit(task);
            return result.get();  // Retrieve the result (count of disjoint pairs)
        } catch (InterruptedException | ExecutionException e) {
            // Handle exceptions, log errors, potentially retry or escalate
            System.err.println("Error processing array: " + e.getMessage());
        }

        return -1; // Indicate an error occurred
    }

