#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Semaphore for Thread-Safe Access
pthread_mutex_t mutex; 
pthread_cond_t cond;

void *accessSharedResource(void *arg) {
  while (1) {
    // Acquire lock (mutex)
    pthread_mutex_lock(&mutex);

    // Critical Section - Access Shared Resource (e.g., Log File, Memory)

    // Release lock (mutex)
    pthread_mutex_unlock(&mutex);
  }
}

int main() {
  // Initialize Semaphore and Condition Variable
  pthread_mutex_init(&mutex, NULL); 
  pthread_cond_init(&cond, NULL);

  // Create Multiple Threads
  pthread_t threads[NUM_THREADS]; // Replace NUM_THREADS with desired number
  for (int i = 0; i < NUM_THREADS; i++) {
    pthread_create(&threads[i], NULL, accessSharedResource, NULL);
  }

  // ... (Main Thread Logic) ...


  // Clean Up Resources
  pthread_mutex_destroy(&mutex);
  pthread_cond_destroy(&cond); 

  return 0;
}
```




