      workerThreads.push_back(std::thread(&FileProcessor::ProcessFiles, this));
    }
  }

  void Stop() {
    processingQueue.emplace(nullptr); // Signal workers to stop

    for (auto& thread : workerThreads) {
      thread.join(); 
    }
  }

  void AddFileForProcessing(const std::string& filePath) {
    std::unique_lock<std::mutex> lock(processingQueueMutex);
    processingQueue.push(filePath);
    cv.notify_one();
  }

