    public string DecryptMessage(string encryptedText, string key, string iv)
    {
        try
        {
            if (key.Length != 24 || iv.Length != 8)
            {
                // Invalid key or IV format
                throw new ArgumentException();
            }

            byte[] encryptedBytes = Convert.FromBase64String(encryptedText);
            TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider();
            tdes.Key = Convert.FromBase64String(key);
            tdes.IV = Convert.FromBase64String(iv);

            using (MemoryStream msDecrypt = new MemoryStream(encryptedBytes))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, tdes.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    using (StreamReader reader = new StreamReader(csDecrypt))
                    {
                        return reader.ReadToEnd();
                    }
                }
            }
        }
        catch (Exception ex)
        {
            // Log decryption error and handle gracefully
            return null; 
        }
    }
}

