    public DecryptorService(IKeyManager keyManager, ILogger<DecryptorService> logger)
    {
        _keyManager = keyManager;
        _logger = logger;
    }

    public T LoadDecryptedData<T>(string filePath, string encryptionKey, string initializationVector) 
    {
        try
        {
            byte[] ivBytes = Convert.FromBase64String(initializationVector);
            using (FileStream fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
            {
                byte[] encryptedData = ReadAllBytes(fileStream);

                if (encryptedData == null || encryptedData.Length == 0)
                {
                    _logger.LogError("Empty encrypted data file.");
                    return default(T);
                }

                byte[] decryptedData = DecryptData(encryptedData, encryptionKey, ivBytes);

                using (MemoryStream memoryStream = new MemoryStream(decryptedData))
                {
                    BinaryFormatter formatter = new BinaryFormatter();
                    return (T)formatter.Deserialize(memoryStream);
                }
            } 
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error loading and deserializing data.");
            throw; // Re-throw to propagate the error
        }  
    }

    private byte[] ReadAllBytes(FileStream fileStream)
    {
        byte[] buffer = new byte[fileStream.Length];
        int bytesRead = 0;
        while (bytesRead < fileStream.Length)
        {
            int count = fileStream.Read(buffer, bytesRead, fileStream.Length - bytesRead);
            if (count == 0) 
                break;
            bytesRead += count;
        }
        return buffer;
    }

    private byte[] DecryptData(byte[] data, string key, byte[] iv)
    {
