        seedLock.lock();
        try {
            // Seed validation logic here based on seedType and seed
            if (isValidSeed(seedType, seed)) {
                rng = new MersenneTwister(seed.toString()); 
            } else {
                throw new IllegalArgumentException("Invalid seed provided.");
