@RestController
@RequestMapping("/resources")
public class ResourceController {

    @Autowired
    private ResourceRepository resourceRepository;

    @Autowired
    private MessageBrokerService messageBrokerService;

    @Autowired
    private ExternalDataService externalDataService;

    @PutMapping("/{id}")
    public ResponseEntity<ResourceResponse> updateResource(@PathVariable String id, @RequestBody UpdateRequest body) {
        // Validate UpdateRequest
        if (!isValidUpdateRequest(body)) {
            return new ResponseEntity<>(HttpStatus.BAD_REQUEST); 
        }
        Resource resource = resourceRepository.findById(id).orElseThrow();

        // Optimistic Locking
        if (resource.getVersion() != body.getVersion()) {
            return new ResponseEntity<>(HttpStatus.CONFLICT);
        }

        // Update Resource Data
        resource.setName(body.getName());
        // ... other updates

        resource.setVersion(resource.getVersion() + 1);
        Resource updatedResource = resourceRepository.save(resource);

        String md5Hash = generateMD5Hash(updatedResource);

        return new ResponseEntity<>(new ResourceResponse(id, md5Hash), HttpStatus.OK);
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Message> deleteResource(@PathVariable String id) {
        // Delete Logic (with optimistic locking and message queueing)

        return new ResponseEntity<>(HttpStatus.ACCEPTED); 
    }
}



