using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Distributed;

public class ProductListingMiddleware
{
    private readonly HttpClient _httpClient;
    private readonly IDistributedCache _cache;
    private readonly IPaymentGatewayService _paymentGateway;
    private readonly IRecommendationEngineService _recommendationEngine;
    private readonly IInventoryManagementService _inventoryManagement;

    public ProductListingMiddleware(HttpClient httpClient, 
                                    IDistributedCache cache, 
                                    IPaymentGatewayService paymentGateway,
                                    IRecommendationEngineService recommendationEngine,
                                    IInventoryManagementService inventoryManagement)
    {
        _httpClient = httpClient;
        _cache = cache;
        _paymentGateway = paymentGateway;
        _recommendationEngine = recommendationEngine;
        _inventoryManagement = inventoryManagement;
    }

    public async Task InvokeAsync(HttpContext context, RequestDelegate next)
    {
        string productId = context.Request.Query["productId"];

        // Cache check for product details
        var cachedProduct = await _cache.GetAsync($"product-{productId}");
        if (cachedProduct != null)
        {
            context.Response.ContentType = "application/json";
            await context.Response.WriteAsync(cachedProduct);
            return;
        }

        // Fetch product details from inventory management system
        var productDetails = await _inventoryManagement.GetProductDetailsAsync(productId);

        if (productDetails != null)
        {
            // Update product details with real-time information from APIs
            productDetails.Price = await _paymentGateway.GetLatestPriceAsync(productId);
            productDetails.Recommendations = await _recommendationEngine.GetProductRecommendationsAsync(productId);

            // Cache product details for future requests
            await _cache.SetAsync($"product-{productId}", 
                                 System.Text.Json.JsonSerializer.SerializeToUtf8Bytes(productDetails), 
                                 TimeSpan.FromMinutes(5)); // Adjust cache duration as needed
        }

        context.Response.ContentType = "application/json";
        await context.Response.WriteAsync(System.Text.Json.JsonSerializer.Serialize(productDetails));
    }
}



```

**Explanation:**

This code demonstrates a basic structure for the asynchronous C# middleware component. 

* It utilizes dependency injection to inject required services like `HttpClient`, `IDistributedCache`, payment gateway, recommendation engine, and inventory management.
* The `InvokeAsync` method handles incoming requests.
*  It employs caching with `IDistributedCache` for frequently accessed product details.
* Data is fetched from the inventory management system and enriched with information from external APIs like payment gateways and recommendation engines.



