MD5_CTX *create_md5_context() {
    MD5_CTX *ctx = malloc(sizeof(MD5_CTX));
    MD5_Init(ctx);
    return ctx;
}

void update_md5_context(MD5_CTX *ctx, const char *data, size_t len) {
    MD5_Update(ctx, data, len);
}

char *compute_md5_hash(const char *input) {
    MD5_CTX *ctx = create_md5_context();
    update_md5_context(ctx, input, strlen(input));
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5_Final(hash, ctx);
    char *hex_hash = malloc(33); // Include null terminator
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        snprintf(hex_hash + i * 2, 3, "%02x", hash[i]);
    }
    return hex_hash;
}

