                    for (ConsumerRecords<String, String> records : kafkaConsumer.poll(Duration.ofMillis(100))) {
                        records.forEach(record -> processMessage(record));
                    }

                    // Process Pulsar messages
                    PulsarMessage message = pulsarConsumer.receive();
                    if (message != null) {
                        processMessage(message);
                        pulsarConsumer.acknowledge(message); 
                    }

                } catch (Exception e) {
                    e.printStackTrace();
                    // Handle exceptions gracefully, retry if possible
                }
            }
        }).start();
    }

    private void processMessage(ConsumerRecord<String, String> record) {
        // Preprocess data, perform quality checks, and publish to downstream services
    }

    private void processMessage(PulsarMessage message) {
        // Preprocess data, perform quality checks, and publish to downstream services
    }
}



```


