fn create_dir_and_set_env(dir_name: &str) {
    if let Ok(existing_path) = env::var("MY_DIR_PATH") {
        println!("Environment variable 'MY_DIR_PATH' already set to {}", existing_path);
    } else {
        let new_dir = format!("{}/", dir_name);
        match std::fs::create_dir(&new_dir) {
            Ok(_) => {
                env::set_var("MY_DIR_PATH", &new_dir);
                println!("Directory '{}' created successfully and environment variable set.", dir_name);
            }
            Err(e) => {
                println!("Error creating directory '{}': {}", dir_name, e);
            }
        }
    }
}

