from MersenneTwister import MersenneTwister

class ResilientRNG:
    def __init__(self, seed_source="default", logging_level="INFO"):
        self.mt = MersenneTwister()
        self.seed_source = seed_source
        self.logging_level = logging_level
        self.logger = setup_logger(self.logging_level)  

    def initialize(self, seed):
        if not isinstance(seed, str):
            raise TypeError("Seed must be a string.")
        try: 
            self.mt.seed(hashlib.sha256(seed.encode()).digest())
        except Exception as e:
            self.logger.error(f"Failed to initialize RNG with seed '{seed}': {e}")
            # Implement fallback strategy here (e.g., use a default seed) 

    def generate_random_int(self, min_value=0, max_value=None):
        if max_value is None:
            max_value = self.mt.max()
        return self.mt.randint(min_value, max_value)

    def generate_random_float(self, min_value=0.0, max_value=1.0):
        return self.generate_random_int(min_value * 10000, max_value * 10000) / 10000

    def generate_random_string(self, length=16):
        return "".join(chr(self.generate_random_int(33, 126)) for _ in range(length))



