// ... Other log processors for binary protocols, etc.

class LogBuffer {
private:
    std::queue<std::string> buffer;
    std::mutex mutex;
    std::condition_variable cv;

public:
    void enqueue(const std::string& log_entry) {
        std::unique_lock<std::mutex> lock(mutex);
        buffer.push(log_entry);
        cv.notify_one(); 
    }

    std::string dequeue() {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this] { return !buffer.empty(); });
        std::string log_entry = buffer.front();
        buffer.pop();
        return log_entry;
    }
};

class LogRouter {
private:
    LogBuffer shared_buffer; 
    std::vector<LogProcessor*> processors;

public:
    void addProcessor(LogProcessor* processor) {
        processors.push_back(processor);
    }

    void processLogs() {
        std::thread consumerThread([this](){
            while (true) {
                std::string log_entry = shared_buffer.dequeue();
                for (auto& processor : processors) {
                    processor->process(log_entry);
                }
            }
        });

        consumerThread.detach(); 
    }
};

int main() {
    LogRouter router;
    router.addProcessor(new JSONLogProcessor());
    router.addProcessor(new CSVLogProcessor());

    // ... Add more processors as needed

    // Start the log processing loop
    router.processLogs(); 

    return 0;
}
