public:
    TransactionProcessor(int numThreads = 4) : threadPool(numThreads) {}

    void processTransactions() {
        while (true) {
            std::unique_lock<std::mutex> lock(transactionQueueMutex);
            cv.wait(lock, [this] { return !transactionQueue.empty(); });

            auto transaction = transactionQueue.front();
            transactionQueue.pop();
            lock.unlock();

            threadPool.enqueue([=]() {
                processTransaction(transaction);
            });
        }
    }

    void addTransaction(const Transaction& transaction) {
        std::unique_lock<std::mutex> lock(transactionQueueMutex);
        transactionQueue.push(transaction);
        cv.notify_one();
    }

