    public async Task<List<string>> ProcessBatch(List<string> encodedMessages, List<string> keys, List<string> ivs)
    {
        if (encodedMessages.Count != keys.Count || encodedMessages.Count != ivs.Count)
        {
            throw new ArgumentException("Number of messages, keys, and IVs must match.");
        }

        var tasks = new List<Task<string>>();
        for (int i = 0; i < encodedMessages.Count; i++)
        {
            tasks.Add(DecryptMessage(encodedMessages[i], keys[i], ivs[i]));
        }

        return await Task.WhenAll(tasks);
    }
}



