public class SecureHashManager 
{
    private readonly IHashingAlgorithmProvider _hashingAlgorithmProvider;
    private readonly ILogger _logger;
    private readonly IRateLimiter _rateLimiter;
    private readonly IMetadataStore _metadataStore; // Add metadata storage

    // Constructor for dependency injection
    public SecureHashManager(IHashingAlgorithmProvider hashingAlgorithmProvider, 
                           ILogger logger, 
                           IRateLimiter rateLimiter, 
                           IMetadataStore metadataStore)
    {
        _hashingAlgorithmProvider = hashingAlgorithmProvider;
        _logger = logger;
        _rateLimiter = rateLimiter;
        _metadataStore = metadataStore;
    }

    public byte[] GenerateHash(byte[] data, HashAlgorithmType algorithmType)
    {
        // Rate limiting check before hashing
        if (!_rateLimiter.AllowRequest())
        {
            _logger.LogWarning("Rate limit exceeded for current user and IP.");
            throw new RateLimitExceededException(); 
        }

        var hashingAlgorithm = _hashingAlgorithmProvider.GetAlgorithm(algorithmType);
        return hashingAlgorithm.ComputeHash(data);
    }
}
```



