public async Task<bool> LoadDecryptedDataAsync(string keyPath, string ivPath, string tagPath, string filePath, Type dataModelType, Action<object> onDecryptedData, Action<byte[]> onKeyRetrieved)
{
    // Key Management Service Interaction (KMS)
    var key = await RetrieveKeyFromKMSAsync(keyPath, onKeyRetrieved);
    var iv = await RetrieveIVFromKMSAsync(ivPath, onKeyRetrieved);
    var tag = await RetrieveTagFromKMSAsync(tagPath, onKeyRetrieved);

    // File Access and Data Retrieval
    byte[] encryptedData = await ReadFileAsync(filePath); 

    // Decryption and Validation
    try
    {
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = key;
            aesAlg.IV = iv;

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            using (MemoryStream msDecrypt = new MemoryStream(encryptedData))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    byte[] decryptedData = new byte[csDecrypt.Length];
                    await csDecrypt.ReadAsync(decryptedData, 0, decryptedData.Length);

                    if (!VerifyTag(tag, encryptedData, decryptedData))
                    {
                        throw new Exception("Decryption failed: Invalid tag.");
                    }

                    // Deserialization
                    object data = DeserializeObject(decryptedData, dataModelType);
                    onDecryptedData(data);
                }
            }
        }
    }
    catch (Exception ex)
    {
        // Log exception details with structured logging and timestamps.
        Console.WriteLine($"Error during decryption: {ex.Message}");
        return false; // Indicate failure
    }

    return true; 
}


