using System;
using System.Diagnostics;

public class WebsiteStarter 
{
    public static string StartWebsite(string directoryPath, string siteName)
    {
        if (!File.Exists(Path.Combine(directoryPath, "web.config")))
            return null; // No web.config file found

        try
        {
            ProcessStartInfo startInfo = new ProcessStartInfo() 
            {
                WorkingDirectory = directoryPath,
                FileName = "iis.exe",  // Assuming IIS is used (adjust accordingly)
                Arguments = $"/start:{siteName}",
                CreateNoWindow = true, // Hide the command window
                UseShellExecute = false
            };

            Process process = Process.Start(startInfo);
            return siteName;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error starting website: {ex.Message}");
            return null; 
        }
    }
}
