char* check_and_append_slash(const char* input, size_t size_limit) {
    if (input == NULL || strlen(input) >= size_limit) {
        return NULL;
    }
    char* output = malloc(size_limit + 2); // Allocate memory for slash and null terminator
    if (output == NULL) {
        return NULL; // Handle allocation failure
    }
    strcpy(output, input);
    strcat(output, "/");
    return output;
}
