class CustomObjectComponent {
private:
    std::vector<std::shared_ptr<CustomObject>> objects;
    std::mutex mutex;
    std::condition_variable cv;

public:
    void updateObject(const std::string& property, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto& obj : objects) {
            if (obj->getProperty() == property) {
                obj->setProperty(value);
                return;
            }
        }

        // Create new object if not found
        auto newObject = std::make_shared<CustomObject>(property, value);
