    }

    public void ExecuteQuery(string query, Dictionary<string, string> parameters)
    {
        // Acquire semaphore using _semaphoreManager
        if (_semaphoreManager.Acquire()) 
        {
            try 
            {
                using (var command = new SqlCommand(query, _sqlConnection))
                {
                    foreach (var parameter in parameters)
                    {
                        command.Parameters.AddWithValue(parameter.Key, parameter.Value);
                    }

                    _rateLimiter.AllowRequest(); // Rate limiting before database call
                    command.ExecuteNonQuery(); 
                }
            }
            catch (Exception ex)
            {
                // Retry logic and backoff implementation
            }
            finally 
            {
                _semaphoreManager.Release(); // Release semaphore after execution
            }
        }
    }

