void insertString(std::forward_list<std::string>& lst, const std::string& find, const std::string& insert) {
  auto it = lst.begin();
  while (it != lst.end() && *it != find) {
    ++it;
  }
  if (it != lst.end()) {
    lst.insert_after(it, insert);
  } else {
    lst.push_back(insert);
  }
}
