  '.js': 'script',
  '.css': 'style'
};

// Handle incoming requests asynchronously
app.post('/process', async (req, res) => {
  const files = req.body.files;

  // Distribute file processing jobs to workers via message broker
  for (const file of files) {
    messageBroker.publish('file_processing', { filename: file });
  }

  res.send({ status: 'Processing initiated' });
});

// Worker process for handling individual files
app.post('/worker', async (req, res) => {
  const { filename } = req.body;

  // Fetch file content from CDN or local storage
  const fileContent = await cdnClient.getFile(filename);

  // Determine MIME type and inject into HTML template
  const mimeType = mimeRules[filename.split('.').pop()];
  const tag = `<${mimeType} id="${filename}" src="${filename}">${fileContent}</${mimeType}>`;

  res.send({ html: tag });
});


app.listen(3000, () => {
  console.log('Microservice listening on port 3000');
});

