// src/client.rs
use reqwest::{Client, Error};
use chrono::{Duration, Utc};

pub struct ClientConfig {
    pub base_url: String,
    pub timeout: Duration,
    pub retries: u32,
    pub retry_backoff: Duration,
}

#[derive(Debug)]
pub enum RequestError {
    NetworkError(Error),
    ApiError(String),
    Timeout,
}

impl From<reqwest::Error> for RequestError {
    fn from(error: reqwest::Error) -> Self {
        RequestError::NetworkError(error)
    }
}


pub struct HttpClient {
    client: Client,
    config: ClientConfig,
}

impl HttpClient {
    pub fn new(config: ClientConfig) -> Self {
        HttpClient {
            client: Client::new(),
            config,
        }
    }

    async fn make_request(&self, method: &str, url: &str, body: Option<String>) -> Result<reqwest::Response, RequestError> {
        let start_time = Utc::now();
        let request = self.client
            .request(method, url)
            .header("Content-Type", "application/json")
            .body(body.unwrap_or_else(|| "".to_string()))
            .timeout(self.config.timeout);

        // Handle potential errors during the request execution
        match request.send().await {
            Ok(response) => Ok(response),
            Err(error) => {
                let elapsed_time = Utc::now() - start_time;
                println!("Request Error: {} | Elapsed Time: {:?}", error, elapsed_time);
                Err(RequestError::NetworkError(error))
            }
        }
    }

}


// src/api.rs
#[derive(Debug)]
pub struct Api {
    name: String,
    base_url: String,
    auth: Box<dyn Auth>, // Placeholder for authentication logic
}

impl Api {
    pub fn new(name: &str, base_url: &str, auth: Box<dyn Auth>) -> Self {
        Api {
            name: name.to_string(),
            base_url: base_url.to_string(),
            auth,
        }
    }

} 



// ... (Other modules and implementations for logging, retry policies, etc.)
