public class NotificationService {

    private static final Logger logger = Logger.getLogger(NotificationService.class.getName());

    private final ExecutorService executorService = Executors.newFixedThreadPool(10); 

    private Map<String, NotificationChannel> channels = new HashMap<>();

    public void AddNotificationChannel(String channelName, String endpoint) {
        if (channels.containsKey(channelName)) {
            logger.warning("Channel '" + channelName + "' already exists.");
            return;
        }

        NotificationChannel channel = new NotificationChannel(channelName, endpoint);
        channels.put(channelName, channel); 
        logger.info("Added notification channel: " + channelName);
    }

    public void SendNotification(String content, List<String> recipientChannels) {
        for (String channelName : recipientChannels) {
            NotificationChannel channel = channels.get(channelName);
            if (channel == null) {
                logger.warning("Invalid channel name: " + channelName);
                continue;
            }
            executorService.execute(() -> {
                try {
                    channel.sendNotification(content);
                } catch (Exception e) {
                    logger.severe("Error sending notification to channel '" + channelName + "': " + e.getMessage());
                    // Implement retry logic with exponential backoff
                }
            }); 
        }
    }

    private class NotificationChannel {

        private final String name;
        private final String endpoint;

