        public EventProcessorModule(IConnectionManager connectionManager, 
                                   ISchemaValidator schemaValidator,
                                   ITransformer transformer, 
                                   IAggregator aggregator, 
                                   ILogger logger)
        {
            _connectionManager = connectionManager;
            _schemaValidator = schemaValidator;
            _transformer = transformer;
            _aggregator = aggregator;
            _logger = logger;
        }

        public async Task ProcessEventsAsync()
        {
            var eventStreams = _connectionManager.GetEventStreams();

            foreach (var stream in eventStreams)
            {
                await foreach (var @event in stream.ReadEvents())
                {
                    try
                    {
                        _schemaValidator.ValidateEvent(@event); // Add validation logic here 
                        var transformedEvent = _transformer.Transform(@event); // Add transformation logic here
                        _aggregator.Aggregate(transformedEvent); // Add aggregation logic here
                    }
                    catch (Exception ex)
                    {
                        _logger.LogError(ex, $"Error processing event: {@event}"); 
                    }
                }
            }
        }
    }

