  private readonly IDbContextFactory<MyDbContext> _dbContextFactory; 

  public DataProcessorWorker(DeserializeService deserializer, IDbContextFactory<MyDbContext> dbContextFactory) {
    _deserializer = deserializer;
    _dbContextFactory = dbContextFactory;
  }

  public async Task ProcessAsync(BinaryData data) {
    using var context = _dbContextFactory.CreateDbContext();
    var processedData = _deserializer.Deserialize(data);
    context.ProcessedData.Add(processedData);
    await context.SaveChangesAsync(); 
  }
}

// Data receiver and queue manager
public class DataReceiver : IDataReceiver {
  private readonly IMessageQueue _queue;

  public DataReceiver(IMessageQueue queue) {
    _queue = queue;
  }

  public async Task ReceiveAsync() {
    while (true) {
      var data = await _queue.ReceiveAsync();
      await _workerDispatcher.DispatchAsync(data); 
    }
  }
}

// Worker dispatcher for distributing tasks to processors
public class WorkerDispatcher {
  private readonly List<DataProcessorWorker> _workers;

  public async Task DispatchAsync(BinaryData data) {
    var worker = _workers[0]; // Simple round-robin distribution
    await worker.ProcessAsync(data);
  }
}



