use std::env;
use std::fs;

fn create_directory_and_set_env(name: &str) {
    let path = format!("{}/{}", env::var("HOME").unwrap_or_else(|_| "/tmp".to_string()), name);

    if let Ok(_) = fs::metadata(&path) {
        println!("Directory {} already exists.", name);
        return;
    }

    match fs::create_dir(&path) {
        Ok(_) => {
            env::set_var(name, &path);
            println!("Created directory {} and set environment variable to {}", name, path);
        }
        Err(e) => panic!("Failed to create directory: {}", e),
    };
}

fn main() {
    create_directory_and_set_env("my_new_dir");
}
