// C++ Configuration Loader (Simplified)

#include <iostream>
#include <fstream>
#include <nlohmann/json.hpp>

using json = nlohmann::json;

class ConfigLoader {
public:
    ConfigLoader(const std::string& filename) : config_file(filename) {
        loadConfig();
    }

    template<typename T>
    T get(const std::string& key) const {
        return config[key].get<T>();
    }

private:
    void loadConfig() {
        std::ifstream file(config_file);
        if (file.is_open()) {
            json configData;
            file >> configData;
            config = configData;
            file.close();
        } else {
            std::cerr << "Failed to open configuration file: " << config_file << std::endl;
        }
    }

    std::string config_file;
    json config; 
};

int main() {
    ConfigLoader loader("config.json");

    // Access configurations
    auto port = loader.get<int>("port");
    auto logLevel = loader.get<std::string>("logLevel");

    return 0;
}


