import java.util.HashMap;
import java.util.Map;

public class UserManagementService {

    private final Map<Integer, User> users = new HashMap<>();

    public void handleRequest(Map<String, String> request) {
        String subAction = request.getOrDefault("sub_action", "create");
        int id = Integer.parseInt(request.getOrDefault("id", "-1")); 

        if (subAction.equals("create")) {
            createUser(request);
        } else if (subAction.equals("update")) {
            updateUser(id, request);
        } else {
            // Handle unsupported sub_action
        }
    }

    private void createUser(Map<String, String> request) {
        User user = new User(
                Integer.parseInt(request.get("id")), 
                request.get("name"), 
                request.get("email"), 
                request.get("password")
        );

        users.put(user.getId(), user);
    }

    private void updateUser(int id, Map<String, String> request) {
        User user = users.get(id);
        if (user != null) {
            user.setName(request.getOrDefault("name", user.getName()));
            user.setEmail(request.getOrDefault("email", user.getEmail()));
            user.setPassword(request.getOrDefault("password", user.getPassword()));
            users.put(id, user);
        } else {
            // Handle user not found
        }
    }

    private class User {
        private int id;
        private String name;
        private String email;
        private String password;

        public User(int id, String name, String email, String password) {
            this.id = id;
            this.name = name;
            this.email = email;
            this.password = password;
        }

        // Getters and setters for user attributes 
    }
}
