void print_usage(char *program_name) {
    printf("Usage: %s [-v] [-o OUTPUT_FILE] INPUT_FILE\n", program_name);
    printf("  -v, --verbose   Increase output verbosity\n");
    printf("  -o, --output FILE Output to specified file\n");
    printf("  INPUT_FILE      File to read data from\n");
}

int main(int argc, char *argv[]) {
    char *input_file = NULL;
    int verbose = 0;
    char *output_file = NULL;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-v") == 0 || strcmp(argv[i], "--verbose") == 0) {
            verbose = 1;
        } else if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output") == 0) {
            if (i + 1 < argc) {
                output_file = argv[++i];
            } else {
                fprintf(stderr, "Error: Missing output file argument\n");
                return 1;
            }
        } else if (input_file == NULL) {
            input_file = argv[i];
        } else {
            fprintf(stderr, "Error: Unknown argument '%s'\n", argv[i]);
            print_usage(argv[0]);
            return 1;
        }
    }

    if (input_file == NULL) {
        print_usage(argv[0]);
        return 1;
    }

    // ... complex transformation logic ...

    return 0;
}
