class ServiceComponent {
 public:
  explicit ServiceComponent(APIClient* api_client, MessagingSystem* messaging_system) :
      api_client_(api_client), messaging_system_(messaging_system) {}

  void start() {
    std::random_device rd;
    std::mt19937 generator(rd());
    std::uniform_int_distribution<> distribution(1, 5);

    auto delay = std::chrono::milliseconds(distribution(generator));
    std::cout << "Service starting in " << delay.count() << "ms\n";
    std::this_thread::sleep_for(delay);
    std::cout << "Service started successfully.\n";
  }

  void stop() {
    std::random_device rd;
    std::mt19937 generator(rd());
    std::uniform_int_distribution<> distribution(1, 5);

    auto delay = std::chrono::milliseconds(distribution(generator));
    std::cout << "Service stopping in " << delay.count() << "ms\n";
    std::this_thread::sleep_for(delay);
    std::cout << "Service stopped successfully.\n";

    // Notify central dashboard about the service stop
    messaging_system_->sendMessage("Service Stopped"); 
  }

 private:
  APIClient* api_client_;
  MessagingSystem* messaging_system_;
};


int main() {
  // Initialize API clients, messaging system, and monitoring platform
  // ...

  // Create an instance of the service component
  ServiceComponent service(api_client, messaging_system);

  // Start and stop the service periodically
  while (true) {
    service.start();
    std::this_thread::sleep_for(std::chrono::seconds(10)); 
    service.stop();
    std::this_thread::sleep_for(std::chrono::seconds(5));
  }

  return 0;
}

