using Microsoft.Azure.EventHubs;
using Newtonsoft.Json;
using RabbitMQ.Client;

public class RealtimeDataPipeline
{
    private EventHubClient _eventHubClient;
    private IConnection _rabbitmqConnection;
    private IDictionary<string, Action<string>> _dataProcessors;

    public RealtimeDataPipeline(string eventHubConnectionString, string rabbitMqConnectionString)
    {
        _eventHubClient = new EventHubClient(eventHubConnectionString);
        var factory = new ConnectionFactory() { HostName = rabbitMqConnectionString };
        _rabbitmqConnection = factory.CreateConnection(); 
        _dataProcessors = new Dictionary<string, Action<string>>();

        // Register data processors for different event types
        _dataProcessors.Add("IoTData", ProcessIoTData);
        _dataProcessors.Add("SocialMediaData", ProcessSocialMediaData);
        _dataProcessors.Add("FinancialMarketData", ProcessFinancialMarketData);
    }

    public void Start()
    {
        // Event Hub Receiver - Consume data from various sources
        var receiver = _eventHubClient.CreateReceiver("$Default", PartitionId.First, DateTime.UtcNow); 
        receiver.OnEventsReceived += async (sender, e) => 
        {
            foreach (EventData eventData in e.Events)
            {
                // Process each received event
                var eventType = DetectEventType(eventData);
                _dataProcessors[eventType](eventData.Body.ToString()); 
