    public async Task<string> AdjustEnvironment(string locationId)
    {
        // Retrieve cached weather data
        WeatherData cachedWeather = _cacheProvider.GetWeatherData(locationId); 

        if (cachedWeather != null)
        {
            _logger.LogDebug($"Using cached weather data for {locationId}");
            return AdjustEnvironmentBasedOnCache(cachedWeather, locationId);
        }

        // Fetch latest weather data from API
        try
        {
            WeatherData weatherData = await _weatherApiClient.GetWeatherAsync(locationId);
            _cacheProvider.SetWeatherData(locationId, weatherData); 
            _logger.LogInformation($"Retrieved fresh weather data for {locationId}");

            return AdjustEnvironmentBasedOnWeather(weatherData, locationId);  
        }
        catch (Exception ex)
        {
            // Handle API errors gracefully, potentially using a fallback mechanism
            _logger.LogError($"Error fetching weather data: {ex.Message}");
            return "Weather data retrieval failed. Environment adjustments on hold."; 
        }   
    }

