// Data Fetching Service
public class EmployeeDataService : IEmployeeDataService
{
    private readonly HttpClient _httpClient;
    private readonly RedisCacheService _redisCache;

    public EmployeeDataService(HttpClient httpClient, RedisCacheService redisCache)
    {
        _httpClient = httpClient;
        _redisCache = redisCache;
    }

    public async Task<List<Employee>> GetEmployeesBySupervisorIdAsync(int supervisorId)
    {
        string cacheKey = $"employees_by_supervisor_{supervisorId}";
        if (_redisCache.Exists(cacheKey))
        {
            return _redisCache.Get<List<Employee>>(cacheKey);
        }

        // Fetch data from HR API
        var response = await _httpClient.GetAsync($"api/employees?supervisorId={supervisorId}");

        if (response.IsSuccessStatusCode)
        {
            var employees = await response.Content.ReadAsAsync<List<Employee>>();
            _redisCache.Set(cacheKey, employees, TimeSpan.FromMinutes(10)); // Cache for 10 minutes
            return employees;
        }
        else
        {
            // Log API error
            throw new Exception($"Error fetching employees: {response.StatusCode}");
        }
    }
}

// Employee Transformation Service
public class EmployeeTransformer : IEmployeeTransformer
{
    public List<FormattedEmployee> TransformEmployees(List<Employee> employees)
    {
        // Transform employee data into desired format
        return employees.Select(e => new FormattedEmployee
        {
            Id = e.Id,
            Name = e.FirstName + " " + e.LastName,
            Department = e.DepartmentId // Assuming DepartmentId maps to a department name
        }).ToList();
    }
}

// Employee Storage Service (e.g., using database)
public class EmployeeStorageService : IEmployeeStorageService
{
    private readonly DatabaseContext _context;

    public EmployeeStorageService(DatabaseContext context)
    {
        _context = context;
    }

    public async Task StoreEmployeesAsync(List<FormattedEmployee> employees)
    {
        // Store formatted employee data in database
        await _context.FormattedEmployees.AddRangeAsync(employees);
        await _context.SaveChangesAsync();
    }
}
