  virtual void processLog(const std::string& logEntry) = 0;

protected:
  std::string _format;
};

class JSONLogProcessor : public LogProcessor {
public:
  JSONLogProcessor() : LogProcessor("JSON") {}

  void processLog(const std::string& logEntry) override {
    // Process JSON log entry
    std::cout << "Processing JSON log: " << logEntry << std::endl;
  }
};

class CSVLogProcessor : public LogProcessor {
public:
  CSVLogProcessor() : LogProcessor("CSV") {}

  void processLog(const std::string& logEntry) override {
    // Process CSV log entry
    std::cout << "Processing CSV log: " << logEntry << std::endl;
  }
};

