using System;
using System.Xml;

public class TileWorldConfig
{
    public int TileSize { get; set; }
    public int WorldWidth { get; set; }
    public int WorldHeight { get; set; }
    public double CameraSpeed { get; set; }
}

public class ConfigLoader
{
    public static TileWorldConfig LoadFromXml(string filePath)
    {
        XmlDocument doc = new XmlDocument();
        doc.Load(filePath);

        XmlNode rootNode = doc.DocumentElement;
        TileWorldConfig config = new TileWorldConfig();

        config.TileSize = int.Parse(rootNode["TileSize"].InnerText);
        config.WorldWidth = int.Parse(rootNode["WorldWidth"].InnerText);
        config.WorldHeight = int.Parse(rootNode["WorldHeight"].InnerText);
        config.CameraSpeed = double.Parse(rootNode["CameraSpeed"].InnerText);

        return config;
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        string filePath = "config.xml"; // Replace with your XML file path
        TileWorldConfig config = ConfigLoader.LoadFromXml(filePath);

        Console.WriteLine($"Tile Size: {config.TileSize}");
        Console.WriteLine($"World Width: {config.WorldWidth}");
        Console.WriteLine($"World Height: {config.WorldHeight}");
        Console.WriteLine($"Camera Speed: {config.CameraSpeed}");
    }
}

