    SessionManager(AuthenticationService* service, int maxSessions = 10000, int idleTimeoutSec = 300) : authService(service), maxSessions(maxSessions), idleTimeoutSec(idleTimeoutSec) {}

    // Add a new session
    void addSession(const std::string& sessionId, const UserProfile& profile, Time startTime) {
        std::lock_guard<std::mutex> lock(mutex);
        sessions[sessionId] = Session(sessionId, profile, startTime);
        cv.notify_all(); // Notify waiting threads about the new session
    }

    // Update a session's information
    void updateSession(const std::string& sessionId, const UserProfile& profile) {
        std::lock_guard<std::mutex> lock(mutex);
        if (sessions.find(sessionId) != sessions.end()) {
            sessions[sessionId].update(profile);
            cv.notify_all(); // Notify waiting threads about the update
        }
    }

    // Retrieve a session by its ID
    Session* getSession(const std::string& sessionId) const {
        std::lock_guard<std::mutex> lock(mutex);
        return &sessions[sessionId];
    }

