class SessionManager {
public:
  SessionManager(size_t maxSessions = 50000) : maxSessions(maxSessions), idleSessionTimeout(60) {}

  // ... (Add, update, retrieve session state methods)

  void pruneIdleSessions() {
    std::lock_guard<std::mutex> lock(sessionsMutex);
    auto now = std::chrono::system_clock::now();

    for (auto it = sessions.begin(); it != sessions.end();) {
      if ((now - it->lastAccessed) > std::chrono::seconds(idleSessionTimeout)) {
        it = sessions.erase(it);
      } else {
        ++it;
      }
    }
  }

private:
  size_t maxSessions;
  int idleSessionTimeout;
  std::mutex sessionsMutex;
  std::queue<Session> sessions; 
};



