using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class DatabaseServiceComponent
{
    private readonly IConfiguration _configuration;
    private readonly IDbConnectionFactory _connectionFactory;
    private readonly ILogger _logger;

    public DatabaseServiceComponent(IConfiguration configuration, IDbConnectionFactory connectionFactory, ILogger logger)
    {
        _configuration = configuration;
        _connectionFactory = connectionFactory;
        _logger = logger;
    }

    public async Task<OperationResult> ExecuteStoredProcedureAsync(string storedProcedureName, Dictionary<string, object> parameters, CancellationToken cancellationToken)
    {
        var serverConfiguration = _configuration.GetDatabaseServers();
        var loadBalancer = new RoundRobinLoadBalancer<SqlConnection>(serverConfiguration);

        try
        {
            using var connection = await loadBalancer.AcquireConnectionAsync(cancellationToken);
            return await ExecuteStoredProcedureOnConnectionAsync(storedProcedureName, parameters, connection, cancellationToken);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error executing stored procedure {StoredProcName}", storedProcedureName);
            throw;
        }
    }

    private async Task<OperationResult> ExecuteStoredProcedureOnConnectionAsync(string storedProcedureName, Dictionary<string, object> parameters, SqlConnection connection, CancellationToken cancellationToken)
    {
        using var command = new SqlCommand(storedProcedureName, connection);
        command.CommandType = CommandType.StoredProcedure;
        foreach (var parameter in parameters)
        {
            command.Parameters.AddWithValue(parameter.Key, parameter.Value);
        }

        try
        {
            await connection.OpenAsync();
            var result = await command.ExecuteScalarAsync();
            return new OperationResult { Result = result };
        }
        catch (SqlException ex)
        {
            _logger.LogError(ex, "Error executing stored procedure {StoredProcName} on server {ServerName}", storedProcedureName, connection.DataSource);
            throw;
        }
    }
}
```



