    private readonly IConnectionManager _connectionManager;
    private readonly IEventValidator _eventValidator;
    private readonly IEventTransformer _eventTransformer;
    private readonly IEventAggregator _eventAggregator;

    public EventStreamProcessor(IConnectionManager connectionManager, 
                               IEventValidator eventValidator, 
                               IEventTransformer eventTransformer, 
                               IEventAggregator eventAggregator)
    {
        _connectionManager = connectionManager;
        _eventValidator = eventValidator;
        _eventTransformer = eventTransformer;
        _eventAggregator = eventAggregator;
    }

    public async Task ProcessEventsAsync()
    {
        foreach (var source in _connectionManager.GetEventSources())
        {
            await foreach (var @event in source.ReceiveEventsAsync())
            {
                if (_eventValidator.Validate(@event))
                {
                    var transformedEvent = _eventTransformer.Transform(@event);

                    _eventAggregator.Aggregate(transformedEvent);
                }
                else
                {
                    // Handle validation errors (logging, retries, failover)
                }
            }
        }
    }
}

