# Registry for Factory Functions (using a distributed locking mechanism)
class JSONSerializerRegistry:
    def __init__(self):
        self.factory_functions = {}  # Lock management here

    def register_factory(self, identifier, factory_function):
        with self._lock:
            if identifier not in self.factory_functions:
                self.factory_functions[identifier] = factory_function

    def get_factory(self, identifier):
        return self.factory_functions.get(identifier)



# Dynamic Subclass Creation (using the registry)
def create_instance_from_json(json_str, identifier):
    serializer_registry = JSONSerializerRegistry() 
    factory_function = serializer_registry.get_factory(identifier)
    if factory_function:
        return factory_function(json_str)
    else:  # Handle unsupported IDs gracefully
        print("Unsupported identifier:", identifier)


