public class LogProcessor {
    private static final Logger logger = LoggerFactory.getLogger(LogProcessor.class); 

    public synchronized String computeMD5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(input.getBytes());
            return HexUtils.encodeHexString(hashBytes);  
        } catch (NoSuchAlgorithmException e) {
            logger.error("MD5 Algorithm not found", e);
            throw new RuntimeException("Error computing MD5 hash.", e);
        }
    }
}
