fn create_directory(dir_name: &str) {
    let path = format!("./{}", dir_name);

    if let Some(existing_path) = std::env::var("CACHE_DIR") {
        if existing_path == path {
            println!("Directory {} already exists and is configured.", dir_name);
            return;
        }
    }

