                std::thread([this](){
                    while (true) {
                        std::unique_lock<std::mutex> lock(dataMutex);
                        cv.wait(lock, [this]{ return !logQueue.empty(); });
                        auto logLine = logQueue.front();
                        logQueue.pop();
                        lock.unlock();

                        // Process log line (extract metrics, generate insights) 
                    }
                }).detach(); // Run in a separate thread for asynchronous processing
            }

            void stop() {
                logSource->stop();
            }

            void enqueueLog(const std::string& logLine) {
                std::lock_guard<std::mutex> lock(dataMutex); 
                logQueue.push(logLine);
                cv.notify_one(); // Wake up the processing thread 
            }
    };



} // namespace LogProcessor

// Example Usage
