    LogSource* fileSource = new FileLogSource("example.log"); // Create a file-based log source
    MetricsExtractor* extractor = new RegexExtractor(); // Create a metrics extractor using regex
    LogProcessor processor(fileSource, extractor); 
    processor.start();

    // ... Add code to handle log data, visualize insights, etc. ...

