using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;

public class BinaryDeserializer 
{
    public CustomDataStructure Deserialize(string filePath) 
    {
        try 
        {
            // Open the file and read its contents
            using (Stream stream = File.OpenRead(filePath))
            {
                // Create a BinaryFormatter instance for deserialization
                BinaryFormatter formatter = new BinaryFormatter();

                // Deserialize the object from the stream
                CustomDataStructure data = (CustomDataStructure)formatter.Deserialize(stream);

                return data; 
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error deserializing binary data: {ex.Message}");
            throw; // Re-throw the exception for higher-level handling
        }   
    }
}


