    pub fn new() -> Result<Self, Box<dyn std::error::Error>> {
        let directory_path = Self::get_config_directory()?;
        Ok(Self { directory_path })
    }

    fn get_config_directory() -> Result<PathBuf, Box<dyn std::error::Error>> {
        // Implement logic to retrieve directory path from configuration service.
        let env_var = "DYNAMIC_DIRECTORY";
        if let Some(path) = env::var(env_var).ok() {
            return Ok(PathBuf::from(path));
        }

        // Initialize and register directory with configuration service.
        info!("No {} environment variable found, initializing default directory.", env_var);
        let new_directory = PathBuf::from("default_directory"); // Replace with logic to determine a suitable path.
        config::register_directory(&new_directory)?;
        Ok(new_directory)
    }

    pub fn generate_float(&self, min: f64, max: f64) -> f64 {
        // Implement logic to generate random float within the specified range.
        let mut rng = rand::thread_rng();
        rng.gen_range(min..max)
    }

    pub fn generate_int(&self, min: i32, max: i32) -> i32 {
        // Implement logic to generate random int within the specified range.
        let mut rng = rand::thread_rng();
        rng.gen_range(min..max + 1)
    }
}


