using System;
using System.Threading.Tasks; // For asynchronous programming
using Microsoft.Azure.ServiceBus; // Example cloud service for messaging

public class RealTimeDataProcessor
{
    private readonly IMessageSender _messageSender;
    private readonly IDataFilter _dataFilter;
    private readonly IDataTransformer _dataTransformer;
    private readonly IDataStorageManager _dataStorageManager; 

    public RealTimeDataProcessor(IMessageSender messageSender, IDataFilter dataFilter, 
                               IDataTransformer dataTransformer, IDataStorageManager dataStorageManager)
    {
        _messageSender = messageSender;
        _dataFilter = dataFilter;
        _dataTransformer = dataTransformer;
        _dataStorageManager = dataStorageManager;
    }

    public async Task ProcessIncomingData(string data)
    {
        // 1. Filtering and Transformation
        var filteredData = _dataFilter.Filter(data);
        var transformedData = _dataTransformer.Transform(filteredData);

        // 2. Storage and Querying
        await _dataStorageManager.StoreDataAsync(transformedData);

        // 3.  Optional: Sending to external systems
        _messageSender.Send(transformedData);
    }
}
```



