import java.util.concurrent.TimeUnit;

public class DisjointPairCounter {

    private UnionFind uf;

    public DisjointPairCounter(int n) {
        uf = new UnionFind(n);
    }

    public int countDisjointPairs(int[] arr) {
        long startTime = System.nanoTime();
        int count = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            for (int j = i + 1; j < arr.length; j++) {
                if (!uf.isConnected(arr[i], arr[j])) {
                    count++;
                    uf.union(arr[i], arr[j]);
                }
            }
        }
        long endTime = System.nanoTime();
        System.out.println("Time taken: " + TimeUnit.NANOSECONDS.toMillis(endTime - startTime) + " ms");
        return count;
    }

    private class UnionFind {
        private int[] parent;
        private int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX != rootY) {
                if (rank[rootX] < rank[rootY]) {
                    parent[rootX] = rootY;
                } else if (rank[rootX] > rank[rootY]) {
                    parent[rootY] = rootX;
                } else {
                    parent[rootY] = rootX;
                    rank[rootX]++;
                }
            }
        }

        public boolean isConnected(int x, int y) {
            return find(x) == find(y);
        }
    }
}


