#include <mutex>
#include <condition_variable>
#include <queue>

class TimeSeriesDataFeed {
 public:
  // Methods for adding, removing, and retrieving data from the feed
  void addData(const std::string& data) {
    std::lock_guard<std::mutex> lock(dataMutex_);
    dataQueue_.push(data);
    cv_.notify_one(); 
  }

  std::string getData() {
    std::unique_lock<std::mutex> lock(dataMutex_);
    cv_.wait(lock, [this] { return !dataQueue_.empty(); });
    std::string data = dataQueue_.front();
    dataQueue_.pop();
    return data;
  }

 private:
  std::queue<std::string> dataQueue_;
  std::mutex dataMutex_;
  std::condition_variable cv_;
};

int main() {
  TimeSeriesDataFeed feed;

  // Simulate adding data from multiple sources in different threads
  std::thread thread1([&feed]() {
    for (int i = 0; i < 10; ++i) {
      feed.addData("Source 1 Data " + std::to_string(i));
      // Add delay to simulate real-time data flow
      std::this_thread::sleep_for(std::chrono::milliseconds(50)); 
    }
  });

  std::thread thread2([&feed]() {
    for (int i = 0; i < 10; ++i) {
      feed.addData("Source 2 Data " + std::to_string(i));
      // Add delay to simulate real-time data flow
      std::this_thread::sleep_for(std::chrono::milliseconds(100)); 
    }
  });

  // Consume data from the feed
  while (true) {
    std::cout << feed.getData() << std::endl;
    // Add delay to simulate processing time
    std::this_thread::sleep_for(std::chrono::milliseconds(200)); 
  }

  thread1.join();
  thread2.join();

  return 0;
}
