  AudioConverter(int numThreads) : threads_(numThreads) {
    for (int i = 0; i < numThreads; ++i) {
      threads_.push_back(std::thread(&AudioConverter::processJob, this));
    }
  }

  ~AudioConverter() {
    // Wait for threads to finish
    for (auto& thread : threads_) {
      thread.join();
    }
  }

  void AddJob(const AudioFileJob& job) {
    jobs_.push(job);
  }

 private:
  void processJob() {
    while (true) {
      AudioFileJob job;
      {
        std::unique_lock<std::mutex> lock(queueMutex_);
        jobs_.wait(lock, [this] { return !jobs_.empty(); });
        job = jobs_.front();
        jobs_.pop();
      }

