    public void processTransaction(@RequestBody TransactionRequest transactionRequest) throws Exception {
        // 1. Data Validation and Transformation
        if (!isValidTransaction(transactionRequest)) {
            throw new IllegalArgumentException("Invalid transaction data");
        }
        TransactionData transformedData = transformTransaction(transactionRequest);

        // 2. Distributed Transaction Management
        TransactionId transactionId = startTransaction(); // Begin distributed transaction
        try {
            // Mainframe Interaction (e.g., update account balances)
            mainframeConnector.updateMainframeData(transformedData, transactionId);

            // Microservice Processing (e.g., generate audit logs, notify downstream services)
            kafkaTemplate.send("transaction-events", transformedData.toString());

            commitTransaction(transactionId); // Commit distributed transaction 
        } catch (Exception e) {
            rollbackTransaction(transactionId); // Rollback on failure
            throw e;
        } finally {
            // Logging and Auditing
            logTransactionDetails(transactionId, transformedData);
        }
    }

