public:
    LogProcessor() : running(true) {}

    void Start() {
        processingThread = std::thread(&LogProcessor::ProcessLogs, this);
    }

    void Stop() {
        running = false;
        processingThread.join();
    }

    void AddLog(const std::string& logData) {
        std::lock_guard<std::mutex> lock(logQueueMutex);
        logQueue.push(logData);
        conditionVariable.notify_one(); 
    }

private:
    void ProcessLogs() {
        while (running) {
            std::unique_lock<std::mutex> lock(logQueueMutex);
            conditionVariable.wait(lock, [this] { return !logQueue.empty() || !running; });
            if (!running) {
                break; 
            }

            std::string logData = logQueue.front();
            logQueue.pop();
            lock.unlock();

            // Process logData (parse, index, store, etc.)

        }
    }

    std::atomic<bool> running;
    std::thread processingThread;
    std::queue<std::string> logQueue;
    std::mutex logQueueMutex;
    std::condition_variable conditionVariable;
};



int main() {
