use tokio::sync::mpsc;
use rand::{RngCore, SeedableRng};

#[tokio::main]
async fn main() {
    // Command-line argument parsing 
    let num_pdus = get_num_pdus_from_args(); 

    // Generate random seed for PDU values
    let mut rng = rand::thread_rng();

    // Create channels for communication between tasks
    let (tx, rx) = mpsc::channel(1024);

    // Spawn workers to generate and process PDUs concurrently
    for _ in 0..num_workers {
        let tx = tx.clone();
        tokio::spawn(async move {
            for _ in 0..num_pdus / num_workers {
                let pdu = generate_pdu(&mut rng);
                tx.send(pdu).await.unwrap(); 
            }
        });
    }

    // Process received PDUs
    while let Some(pdu) = rx.recv().await {
        process_pdu(&pdu);
    }
}


fn generate_pdu(rng: &mut impl RngCore) -> NFAPI_CRC_INDICATION_PDU_T {
    let rx_ue_information_tag = rng.next_u32();
    let rnti = rng.next_u16();
    let crc_indication_rel8_tag = rng.next_u8();
    let crcflag = rng.next_bool(); // Generate random CRCFLAG value

