}


fn main() -> Result<(), Box<dyn Error>> {
    let timestamp = Local::now().format("%Y-%m-%d_%H-%M-%S");
    let new_dir_path = PathBuf::from(format!("crc_indications_{}", timestamp));
    if !fs::metadata(&new_dir_path).is_ok() {
        fs::create_dir(&new_dir_path)?;
        std::env::set_var("CRC_INDICATIONS_DIR", new_dir_path.to_str().unwrap()); 
