public:
    void enqueue(const Event& event) {
        std::lock_guard<std::mutex> lock(queueMutex);
        eventQueue.push(event);
    }

    void processEvents() {
        while (true) {
            std::lock_guard<std::mutex> lock(queueMutex);
            if (!eventQueue.empty()) {
                Event event = eventQueue.front();
                eventQueue.pop();
                // Process the event here
                std::cout << "Processing event: type=" << event.type << ", data=" << event.data << std::endl;
            }
        }
    }
};

int main() {
    EventProcessor processor;

    std::thread processingThread(&EventProcessor::processEvents, &processor);

    // Simulate incoming events
    for (int i = 0; i < 10; ++i) {
        Event event{"sensor", "value" + std::to_string(i)};
        processor.enqueue(event);
    }

    processingThread.join(); 
    return 0;
}
```




