// File processing pipeline logic 
const fs = require('fs');
const path = require('path');
const { Worker } = require('worker_threads');

const config = require('./config'); // Load configuration from a dedicated file

// Placeholder for plugin system
const validateData = (data) => { /* Validation logic here */ }; 


async function processFiles(directory) {
  const files = fs.readdirSync(directory);
  const workers = [];

  for (const file of files) {
    const filePath = path.join(directory, file);
    if (fs.statSync(filePath).isFile()) {
      workers.push(new Worker('./worker.js', { workerData: { filePath } }));
    }
  }

  for (const worker of workers) {
    await new Promise((resolve) => worker.on('exit', resolve)); 
  }
}

