char* truncate_and_append(const char* input, size_t size_limit) {
  if (strlen(input) <= size_limit) {
    char *result = malloc(size_limit + 2); 
    strncpy(result, input, size_limit);
    result[size_limit] = '/';
    result[size_limit + 1] = '\0';
    return result;
