#[derive(Clone)]
pub struct HttpClient {
    client: Client,
    log_level: log::LevelFilter,
    backoff: BackoffStrategy, // Implement a custom backoff strategy
}

impl HttpClient {
    pub fn new(log_level: log::LevelFilter) -> Result<Self, Box<dyn std::error::Error>> {
        // Configure reqwest client with desired settings (e.g., connection pooling)
        let client = Client::new();

        Ok(HttpClient {
            client,
            log_level,
            backoff: DefaultBackoffStrategy {}, // Initialize default backoff strategy
        })
    }

    // Implement methods for sending requests to various URLs, including:
    // - GET 
    // - POST
    // - PUT
    // ...

    // Example method for making a GET request with retry logic:
    pub async fn get(&self, url: &str) -> Result<reqwest::Response, Error> {
        let start_time = Instant::now();

        loop {
            match self.client.get(url).send().await {
                Ok(response) => {
                    debug!("Request to {} completed in {:.2?}", url, start_time.elapsed());
                    return Ok(response);
                }
                Err(e) => {
                    warn!("Error making request to {}: {}", url, e);

                    // Implement backoff strategy based on error type and log level
                    self.backoff.apply(); 
                }
            }
        }
    }
}

#[derive(Debug)]
pub struct DefaultBackoffStrategy {}

impl BackoffStrategy for DefaultBackoffStrategy {
    fn apply(&self) {
        // Implement a simple exponential backoff strategy here (e.g., doubling the wait time on each retry)
    }
}


