// File Handling, Compression & Deserialization
public class DataProcessorService 
{
    private readonly ICompressionService _compressionService; // Inject compression service for handling zip/gzip

    public DataProcessorService(ICompressionService compressionService)
    {
        _compressionService = compressionService;
    }

    public async Task<object> ProcessDataFromFileAsync(string filePath)
    {
        var extension = Path.GetExtension(filePath).ToLower();

        if (extension == ".json")
        {
            return await DeserializeJsonAsync(filePath); 
        }
        else if (extension == ".csv")
        {
            return await DeserializeCsvAsync(filePath);
        }
        // Add other file type deserialization logic here...
        else if (extension.StartsWith(".zip") || extension.StartsWith(".gz"))
        {
            var decompressedData = await _compressionService.DecompressAsync(filePath); 
            return ProcessDataFromFileAsync(decompressedData); // Recursively process decompressed data
        }
        throw new ArgumentException($"Unsupported file format: {extension}");
    }

