using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json; // Assuming you'll use Newtonsoft for JSON serialization

namespace EmployeeDataFetcher
{
    public class EmployeeDataFetcherService
    {
        private readonly string _hrApiUrl;
        private readonly HttpClient _httpClient;
        private readonly RedisCache _redisCache;
        private readonly ILoggingService _loggingService;

        // Constructor with dependencies injection 
        public EmployeeDataFetcherService(string hrApiUrl, HttpClient httpClient, RedisCache redisCache, ILoggingService loggingService)
        {
            _hrApiUrl = hrApiUrl;
            _httpClient = httpClient;
            _redisCache = redisCache;
            _loggingService = loggingService;
        }

        public async Task<List<Employee>> GetEmployeesForSupervisor(int supervisorId)
        {
            var cacheKey = $"supervisor_{supervisorId}_employees";
            if (_redisCache.Exists(cacheKey))
            {
                // Fetch from cache
                return JsonConvert.DeserializeObject<List<Employee>>(_redisCache.Get(cacheKey));
            }

            try
            {
                var response = await _httpClient.GetAsync($"{_hrApiUrl}/supervisors/{supervisorId}/employees");

                if (response.IsSuccessStatusCode)
                {
                    var employees = JsonConvert.DeserializeObject<List<Employee>>(await response.Content.ReadAsStringAsync());
                    _redisCache.Set(cacheKey, JsonConvert.SerializeObject(employees), TimeSpan.FromMinutes(15)); // Cache for 15 minutes
                    return employees;
                }
                else
                {
                    _loggingService.LogError($"HR API request failed: {response.StatusCode} - {await response.Content.ReadAsStringAsync()}");
                    // Handle API error appropriately, maybe retry with exponential backoff
                    throw new Exception("Error fetching employee data from HR API"); 
                }
            }
            catch (Exception ex)
            {
                _loggingService.LogError($"Error fetching employee data: {ex.Message}");
                throw; // Re-throw for higher level handling
            }
        }
    }

    // ... Employee class definition ... 
    public interface ILoggingService 
    {
        void LogError(string message);
    }

    // ... RedisCache implementation ...
}

