// Placeholder for logging service interfaces
class LogService {
public:
    virtual void logMessage(const std::string& message) = 0;
};

class JSONLogService : public LogService {
public:
    void logMessage(const std::string& message) override {
        // Implement JSON logging logic here
    }
};

class CSVLogService : public LogService {
public:
    void logMessage(const std::string& message) override {
        // Implement CSV logging logic here
    }
};

// Placeholder for data format parser 
class DataParser {
public:
    virtual std::string parseLog(const std::string& rawData) = 0;
};

class JSONDataParser : public DataParser {
public:
    std::string parseLog(const std::string& rawData) override {
        // Implement JSON parsing logic here
    }
};

class LogProcessor {
private:
    std::queue<std::string> logQueue;
    std::mutex queueMutex;
    std::condition_variable queueCondition;
    LogService* activeLogService;
    DataParser* activeDataParser;

public:
    LogProcessor(LogService* service, DataParser* parser) : 
        activeLogService(service), activeDataParser(parser) {}

    void processLogs() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            queueCondition.wait(lock, [this] { return !logQueue.empty(); }); 

            std::string logMessage = logQueue.front();
            logQueue.pop();
            lock.unlock();

            std::string processedData = activeDataParser->parseLog(logMessage);
            activeLogService->logMessage(processedData);
        }
    }

    void addLogMessage(const std::string& logEntry) {
        std::unique_lock<std::mutex> lock(queueMutex);
        logQueue.push(logEntry);
        queueCondition.notify_one(); 
    }
};


int main() {
    // Example usage:
    JSONLogService jsonLogger;
    JSONDataParser jsonParser;
    LogProcessor processor(&jsonLogger, &jsonParser);

    std::thread processingThread([&processor]() { processor.processLogs(); });

    // Simulate adding log messages 
    for (int i = 0; i < 100; ++i) {
        processor.addLogMessage("Example Log Message " + std::to_string(i));
    }

    processingThread.join(); 

    return 0;
}
```


**Note:** This is a simplified example to demonstrate the basic structure. A real-world implementation would require significantly more code and complexity to address all the requirements mentioned in the prompt.']

