NFAPI_CRC_COLLECTION_T* init_nfapi_crc_collection(size_t initial_size) {
    NFAPI_CRC_COLLECTION_T *collection = (NFAPI_CRC_COLLECTION_T*)malloc(sizeof(NFAPI_CRC_COLLECTION_T));
    if (collection == NULL) {
        fprintf(stderr, "Memory allocation failed!\n");
        return NULL;
    }

    collection->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T)); 
    if (collection->data == NULL) {
        fprintf(stderr, "Memory allocation failed!\n");
        free(collection);
        return NULL;
    }

    collection->size = 0;
    collection->capacity = initial_size;
    return collection;
}

// Add a new NFAPI_CRC_INDICATION_PDU_T structure to the collection, ensuring unique RNTI values.
int add_nfapi_crc_pdu(NFAPI_CRC_COLLECTION_T *collection, uint32_t rnti) {
    if (collection->size == collection->capacity) {
        // Resize the collection if it's full
        collection->capacity *= 2; // Double the capacity

        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(collection->data, collection->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            fprintf(stderr, "Memory reallocation failed!\n");
            return -1; // Indicate error
        }
        collection->data = new_data; 
    }

    // Generate a random CRCFLAGS value
    srand(time(NULL));
    collection->data[collection->size].CRCFLAGS = rand() % 256;

    collection->data[collection->size].RNTI = rnti; // Assign the provided RNTI
    collection->size++; 

