private:
    std::queue<std::string> logQueue;
    std::mutex queueMutex;
    bool running;

public:
    LogProcessor(LoggingSystem* loggingSystem, AnalyticsPlatform* analyticsPlatform, NotificationService* notificationService) : 
        loggingSystem(loggingSystem), analyticsPlatform(analyticsPlatform), notificationService(notificationService) {
        running = true;
        std::thread processingThread(&LogProcessor::processLogs, this);
    }

    void enqueueLog(const std::string& logMessage) {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            logQueue.push(logMessage);
        }
        notificationService->notify("New log message enqueued.");
    }

    void stop() {
        running = false;
    }

private:
    void processLogs() {
        while (running) {
            std::string logMessage;
            {
                std::lock_guard<std::mutex> lock(queueMutex);
                if (!logQueue.empty()) {
                    logMessage = logQueue.front();
                    logQueue.pop();
                }
            }

            if (!logMessage.empty()) {
                // Process the log message:
                loggingSystem->writeLog("Processed log: " + logMessage);
                analyticsPlatform->sendData(logMessage);
            }
        }
    }

