std::mt19937 generator(rd()); // Mersenne Twister 19937 engine seeded with rd()
std::uniform_int_distribution<> distribution(1, 2); // Distribute between 1 and 2

bool cooldown = false;
auto lastAttackTime = std::chrono::system_clock::now();

void selectAndExecuteAttack() {
  if (cooldown) {
    auto currentTime = std::chrono::system_clock::now();
    std::chrono::duration<double> elapsed = currentTime - lastAttackTime;
    if (elapsed.count() >= 9) { // Cooldown duration is 9 seconds
      cooldown = false;
      lastAttackTime = currentTime;
    }
    return;
  }

  int attackNumber = distribution(generator);
  std::cout << "Attacking with number: " << attackNumber << std::endl;
  cooldown = true;
  lastAttackTime = std::chrono::system_clock::now();
}

int main() {
  while (true) {
    selectAndExecuteAttack();
    std::this_thread::sleep_for(std::chrono::seconds(1)); 
  }
  return 0;
}
