#include <openssl/aes.h>
#include <openssl/sha.h>

// Function to initialize AES-256-CBC cipher with given password
int init_aes_cipher(const char *password, int password_len, AES_KEY *key, unsigned char *iv) {
    SHA256_CTX sha256;
    unsigned char hash[SHA256_DIGEST_LENGTH];

    // Derive the key using SHA-256
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password, password_len);
    SHA256_Final(hash, &sha256);

    // Extract AES key from the hash 
    memcpy(key->enc, hash, 32);  

    // Set IV length to 16 bytes
    memset(iv, 0, 16); 

