class LogProcessor {
private:
  std::queue<std::string> logQueue;
  std::mutex queueMutex;
  std::vector<LogService*> services; 

public:
  LogProcessor() {
    // Initialize and register your logging services here
    services.push_back(new JsonLogService());
    services.push_back(new CsvLogService()); 
  }

  void processLogs() {
    while (true) {
      std::unique_lock<std::mutex> lock(queueMutex);
      if (!logQueue.empty()) {
        std::string logMessage = logQueue.front();
        logQueue.pop();
        lock.unlock();

        for (LogService* service : services) {
          service->sendLog(logMessage); 
        }
      } else {
        // Handle queue emptiness, e.g., sleep or check for new logs
      }
    }
  }

  void enqueueLog(const std::string& logMessage) {
    std::lock_guard<std::mutex> lock(queueMutex);
    logQueue.push(logMessage);
  }
};

int main() {
  LogProcessor processor;
  std::thread processingThread(&LogProcessor::processLogs, &processor);

  // Simulate log generation and enqueueing
  for (int i = 0; i < 1000; ++i) {
    processor.enqueueLog("This is a log message " + std::to_string(i));
  }

  processingThread.join();
  return 0;
}
